export const initial = { index: 0, answers: [], finished: false };

export function quizReducer(state, action) {
  if (state.finished && action.type !== "reset") return state;   // reject after finish.
  switch (action.type) {
    case "answered":
      return { ...state, answers: [...state.answers.slice(0, state.index), action.choice] };
    case "next":
      return { ...state, index: state.index + 1 };
    case "finished":
      return { ...state, finished: true };
    case "reset":
      return initial;
    default:
      throw new Error(`Unknown action: ${action.type}`);
  }
}

// In the component.
const [quiz, dispatch] = useReducer(quizReducer, initial);
<button type="button" onClick={() => dispatch({ type: "answered", choice: 2 })}>B</button>
```

| Part | Job |
|---|---|
| action. | what happened, plus data. |
| reducer. | pure rules: state + action to next state. |
| dispatch. | send an action from a handler. |
| same state returned. | transition rejected, no re-render. |

